fn stored_group(
    name: &str,
    value: &str,
) -> service_com_amazonaws_migrationhubstrategy_awsmigrationhubstrategyrecommendation::ops::types::Group
{
    service_com_amazonaws_migrationhubstrategy_awsmigrationhubstrategyrecommendation::ops::types::Group {
        name: Some(name.to_string()),
        value: Some(value.to_string()),
    }
}

/// Send one path-style request to the emulator's S3 front door, returning the HTTP status
/// and the raw body.
async fn s3(router: &MultiServiceRouter, method: &str, path: &str) -> (u16, Vec<u8>) {
    let request = ::http::Request::builder()
        .method(method)
        .uri(path)
        .header("host", "s3.eu-west-1.amazonaws.com")
        .header("authorization", SIGNED_FOR_S3)
        .body(Bytes::new())
        .expect("the test request is well formed");
    let response = router.dispatch(request).await;
    let status = response.status().as_u16();
    (status, response.into_body().as_ref().to_vec())
}

/// How the account's report data bucket came to be configured: the start call that named
/// it. Both members documented as the bucket this service uploads to.
#[derive(Clone, Copy, Debug)]
enum Configured {
    /// `StartAssessmentRequest$s3bucketForReportData`.
    ByAssessment,
    /// `StartImportFileTaskRequest$s3bucketForReportData`.
    ByImport,
}

/// Name `bucket` as the account's report data bucket through the start call `by`.
async fn configure_report_bucket(
    case: &str,
    router: &MultiServiceRouter,
    by: Configured,
    bucket: &str,
) {
    let answer = match by {
        Configured::ByAssessment => {
            call(
                router,
                "POST",
                "/start-assessment",
                Some(json!({
                    "s3bucketForReportData": bucket,
                    "s3bucketForAnalysisData": ANALYSIS_BUCKET,
                })),
            )
            .await
        }
        Configured::ByImport => {
            call(
                router,
                "POST",
                "/start-import-file-task",
                Some(json!({
                    "name": "inventory",
                    "S3Bucket": IMPORT_BUCKET,
                    "s3key": "servers.json",
                    "s3bucketForReportData": bucket,
                })),
            )
            .await
        }
    };
    assert_eq!(
        answer.status, 200,
        "case {case:?}: naming {bucket:?} as the report data bucket must succeed, got {} with \
         {:?}",
        answer.status, answer.body
    );
}

/// One row of the table.
struct Case {
    what: &'static str,
    /// The start call that configured the account's report data bucket.
    configured: Configured,
    /// The `StartRecommendationReportGeneration` request.
    request: Value,
    /// The `OutputFormat` the task's file is in, which is the extension of its key.
    format: &'static str,
    /// How many servers of the seeded inventory the request's filter selects.
    servers_in_scope: usize,
    /// Which servers of the inventory the file must report on, by id.
    reported_servers: &'static [&'static str],
    /// Which application components it must report on, by id.
    reported_components: &'static [&'static str],
}

/// Every row: each `OutputFormat` value and an absent one, each start call that can
/// configure the bucket, and a scope covering the whole portfolio, part of it and none of
/// it.
fn cases() -> Vec<Case> {
    vec![
        Case {
            what: "no members at all, so the default format over the whole portfolio",
            configured: Configured::ByAssessment,
            request: json!({}),
            format: OUTPUT_FORMAT_EXCEL,
            servers_in_scope: 4,
            reported_servers: &["0a", "0b", "1a", "2b"],
            reported_components: &["b00000000001", "b00000000002"],
        },
        Case {
            what: "the JSON format over the whole portfolio",
            configured: Configured::ByAssessment,
            request: json!({"outputFormat": OUTPUT_FORMAT_JSON}),
            format: OUTPUT_FORMAT_JSON,
            servers_in_scope: 4,
            reported_servers: &["0a", "0b", "1a", "2b"],
            reported_components: &["b00000000001", "b00000000002"],
        },
        Case {
            what: "the bucket named by an import, and one group two servers came in with",
            configured: Configured::ByImport,
            request: json!({
                "outputFormat": OUTPUT_FORMAT_JSON,
                "groupIdFilter": [{"name": "ExternalId", "value": "wave-1"}],
            }),
            format: OUTPUT_FORMAT_JSON,
            servers_in_scope: 2,
            reported_servers: &["0a", "0b"],
            reported_components: &["b00000000001", "b00000000002"],
        },
        Case {
            what: "the Excel format scoped to the other GroupName, which one server carries",
            configured: Configured::ByImport,
            request: json!({
                "outputFormat": OUTPUT_FORMAT_EXCEL,
                "groupIdFilter": [{"name": "ExternalSourceType", "value": "MPA"}],
            }),
            format: OUTPUT_FORMAT_EXCEL,
            servers_in_scope: 1,
            reported_servers: &["1a"],
            reported_components: &[],
        },
        Case {
            what: "a group no server came in with, so a report of nothing",
            configured: Configured::ByAssessment,
            request: json!({
                "outputFormat": OUTPUT_FORMAT_JSON,
                "groupIdFilter": [{"name": "ExternalId", "value": "wave-9"}],
            }),
            format: OUTPUT_FORMAT_JSON,
            servers_in_scope: 0,
            reported_servers: &[],
            reported_components: &[],
        },
        Case {
            what: "an empty filter scopes nothing, so again the whole portfolio",
            configured: Configured::ByAssessment,
            request: json!({"outputFormat": OUTPUT_FORMAT_EXCEL, "groupIdFilter": []}),
            format: OUTPUT_FORMAT_EXCEL,
            servers_in_scope: 4,
            reported_servers: &["0a", "0b", "1a", "2b"],
            reported_components: &["b00000000001", "b00000000002"],
        },
    ]
}

/// A completed task reports the report file it wrote — the account's report data bucket and
/// the key inside it — and the object that pair names is there to fetch, in the format the
/// call asked for and holding the portfolio the task covered.
#[tokio::test]
async fn a_completed_task_reports_the_report_file_it_wrote() {
    let mut keys_seen: Vec<String> = Vec::new();

    for case in cases() {
        // One emulator per row: each row configures the account's report bucket through its
        // own start call, and only one report generation task runs at a time.
        let (router, _engine) = emulator();
        configure_report_bucket(case.what, &router, case.configured, REPORT_BUCKET).await;
        let what = case.what;

        let started = start_report(&router, case.request.clone()).await;
        assert_eq!(
            started.status, 200,
            "case {what:?}: expected HTTP 200 from StartRecommendationReportGeneration, got {} \
             with {:?}",
            started.status, started.body
        );
        let id = started.string("/id");

        // The report file is the artifact of a FINISHED task, so a running task names no
        // location yet. Whenever a read finds the task still running, that is what it must
        // report — asserted off the STATUS rather than off the host clock.
        let running = report_details(&router, &id).await;
        if running.string("/recommendationReportDetails/status") == REPORT_IN_PROGRESS {
            for member in ["/s3Bucket", "/s3Keys"] {
                let pointer = format!("/recommendationReportDetails{member}");
                assert_eq!(
                    at(&running.body, &pointer),
                    Value::Null,
                    "case {what:?}: a task still generating names no {member} yet, got {:?}",
                    at(&running.body, &pointer)
                );
            }
        }

        // Nothing but the clock drives the terminal status: the read is repeated until the
        // task has it.
        let settled = settled_details(&router, &id).await;
        let bucket = settled.string("/recommendationReportDetails/s3Bucket");
        assert_eq!(
            bucket, REPORT_BUCKET,
            "case {what:?}: s3Bucket is the bucket the account named for report data, got \
             {bucket:?}"
        );
        assert!(
            !bucket.trim().is_empty() && bucket.len() <= MAX_S3_BUCKET,
            "case {what:?}: s3Bucket must be a non-blank name within {MAX_S3_BUCKET} \
             characters, got {bucket:?}"
        );
        let keys = at(&settled.body, "/recommendationReportDetails/s3Keys");
        let keys: Vec<String> = keys
            .as_array()
            .unwrap_or_else(|| panic!("case {what:?}: expected a list of s3Keys, got {keys:?}"))
            .iter()
            .map(|key| key.as_str().unwrap_or_default().to_string())
            .collect();
        assert_eq!(
            keys.len(),
            1,
            "case {what:?}: the task wrote one report file, so it names one key, got {keys:?}"
        );
        let key = keys[0].clone();
        keys_seen.push(key.clone());
        assert!(
            key.contains(&id),
            "case {what:?}: the key names the task that wrote the file, got {key:?} for {id:?}"
        );
        let extension = if case.format == OUTPUT_FORMAT_JSON {
            ".json"
        } else {
            ".xlsx"
        };
        assert!(
            key.ends_with(extension),
            "case {what:?}: a {} report is written as a {extension} file, got {key:?}",
            case.format
        );

        // The pair is followable: the object the key names is in the bucket reported beside
        // it, and it is in the format the call asked for.
        let (status, body) = s3(&router, "GET", &format!("/{bucket}/{key}")).await;
        assert_eq!(
            status,
            200,
            "case {what:?}: the report file at s3://{bucket}/{key} must be readable, got \
             {status} with {} byte(s)",
            body.len()
        );
        if case.format == OUTPUT_FORMAT_JSON {
            assert_json_report(what, &body, &case, &id);
        } else {
            assert!(
                body.starts_with(ZIP_MAGIC),
                "case {what:?}: an Excel report is an Excel workbook, got {} byte(s) opening \
                 with {:?}",
                body.len(),
                &body[..body.len().min(4)]
            );
            // The workbook carries the rows of the scope, so it grows with what is in it:
            // an empty container could not hold the sheet names the report needs.
            assert!(
                body.len() > ZIP_MAGIC.len(),
                "case {what:?}: the Excel report must hold the workbook, got {} byte(s)",
                body.len()
            );
        }

        // The message reports the task's own scope and what became of its file, and stays
        // inside the member's published bound.
        let message = settled.string("/recommendationReportDetails/statusMessage");
        assert!(
            !message.trim().is_empty() && message.len() <= STATUS_MESSAGE_MAX,
            "case {what:?}: expected a non-blank status message within {STATUS_MESSAGE_MAX} \
             characters, got {message:?}"
        );
        assert!(
            message.contains(&case.servers_in_scope.to_string()),
            "case {what:?}: {} server(s) are in scope, but the message does not report that \
             count: {message:?}",
            case.servers_in_scope
        );
        assert!(
            message.contains(case.format),
            "case {what:?}: the message reports the format the report was generated in, got \
             {message:?}"
        );

        // Reading twice reports the same location: the file is not re-written per read.
        let again = report_details(&router, &id).await;
        assert_eq!(
            again.body, settled.body,
            "case {what:?}: reading the task twice must report the same record, got {:?} then \
             {:?}",
            settled.body, again.body
        );
    }

    assert_eq!(
        keys_seen.len(),
        cases().len(),
        "every row writes a report file of its own, got {keys_seen:?}"
    );
}

/// Every value of a JSON report file comes from the task and the portfolio it covered.
fn assert_json_report(what: &str, body: &[u8], case: &Case, id: &str) {
    let document: Value = serde_json::from_slice(body).unwrap_or_else(|error| {
        panic!(
            "case {what:?}: a Json report is a JSON document ({error}): {:?}",
            String::from_utf8_lossy(body)
        )
    });
    for (pointer, expected) in [
        ("/recommendationTaskId", json!(id)),
        ("/outputFormat", json!(case.format)),
        ("/serversInScope", json!(case.servers_in_scope)),
    ] {
        assert_eq!(
            at(&document, pointer),
            expected,
            "case {what:?}: the report's {pointer} must be {expected:?}, got {:?}",
            at(&document, pointer)
        );
    }
    let reported: Vec<String> = at(&document, "/servers")
        .as_array()
        .unwrap_or(&Vec::new())
        .iter()
        .map(|server| at(server, "/serverId").as_str().unwrap_or_default().to_string())
        .collect();
    assert_eq!(
        reported, case.reported_servers,
        "case {what:?}: the report lists the servers in scope, got {reported:?}"
    );
    let components: Vec<String> = at(&document, "/applicationComponents")
        .as_array()
        .unwrap_or(&Vec::new())
        .iter()
        .map(|component| {
            at(component, "/applicationComponentId")
                .as_str()
                .unwrap_or_default()
                .to_string()
        })
        .collect();
    assert_eq!(
        components, case.reported_components,
        "case {what:?}: the report lists the components running on those servers, got \
         {components:?}"
    );
    // The recommendation a server holds travels into the file it is reported in.
    if case.reported_servers.contains(&"0a") {
        let first = at(&document, "/servers/0");
        for (pointer, expected) in [
            ("/serverName", json!("web-01")),
            ("/osType", json!("Linux")),
            ("/strategy", json!("Rehost")),
        ] {
            assert_eq!(
                at(&first, pointer),
                expected,
                "case {what:?}: the first server's {pointer} must be {expected:?}, got {:?}",
                at(&first, pointer)
            );
        }
    }
}

/// An account that named no bucket for the reports the service generates has nowhere for a
/// report file to go: its task names no location at all and says why, rather than naming an
/// object nothing wrote — and the same holds once the account's bucket is replaced by
/// another, where the NEXT task's file goes.
#[tokio::test]
async fn a_task_names_a_location_only_for_a_file_that_was_written() {
    let (router, _engine) = emulator();

    // No start call has named a report data bucket yet.
    let id = start_report(&router, json!({"outputFormat": OUTPUT_FORMAT_JSON}))
        .await
        .string("/id");
    // The task of an account with no report data bucket still reaches its terminal status:
    // the poll below is what asserts it.
    let settled = settled_details(&router, &id).await;
    for member in ["/s3Bucket", "/s3Keys"] {
        let pointer = format!("/recommendationReportDetails{member}");
        assert_eq!(
            at(&settled.body, &pointer),
            Value::Null,
            "with no report data bucket there is no file, so {member} must be absent, got {:?}",
            at(&settled.body, &pointer)
        );
    }
    let message = settled.string("/recommendationReportDetails/statusMessage");
    assert!(
        message.len() <= STATUS_MESSAGE_MAX && message.contains("no Amazon S3 bucket"),
        "the message must say the account configured no bucket for report data, got {message:?}"
    );

    // The account names one bucket, then another: the next task's file goes to the latest
    // one, so the location a task reports is the account's configuration at the time it ran.
    let mut located: Vec<(String, String)> = Vec::new();
    for bucket in [REPORT_BUCKET, OTHER_REPORT_BUCKET] {
        configure_report_bucket("a replaced bucket", &router, Configured::ByImport, bucket).await;
        let id = start_report(&router, json!({"outputFormat": OUTPUT_FORMAT_JSON}))
            .await
            .string("/id");
        let settled = settled_details(&router, &id).await;
        assert_eq!(
            settled.string("/recommendationReportDetails/s3Bucket"),
            bucket,
            "the file goes to the bucket the account named last, got {:?}",
            settled.body
        );
        let key = at(&settled.body, "/recommendationReportDetails/s3Keys/0")
            .as_str()
            .unwrap_or_default()
            .to_string();
        let (status, body) = s3(&router, "GET", &format!("/{bucket}/{key}")).await;
        assert_eq!(
            status,
            200,
            "the reported location s3://{bucket}/{key} must name a readable object, got {status} \
             with {} byte(s)",
            body.len()
        );
        located.push((bucket.to_string(), key));
    }
    assert_ne!(
        located[0], located[1],
        "each task writes its own report file, got {located:?}"
    );
}

/// The reported location is not derived from the read: a task's file is written once, by the
/// start call, so polling the task many times leaves exactly one object in the bucket.
#[tokio::test]
async fn polling_a_task_writes_no_further_report_file() {
    let (router, _engine) = emulator();
    configure_report_bucket(
        "one object per task",
        &router,
        Configured::ByAssessment,
        REPORT_BUCKET,
    )
    .await;
    let id = start_report(&router, json!({"outputFormat": OUTPUT_FORMAT_JSON}))
        .await
        .string("/id");

    // Poll until the clock has given the task its terminal status, which is what a client
    // following the documented flow does.
    let settled = settled_details(&router, &id).await;
    let key = at(&settled.body, "/recommendationReportDetails/s3Keys/0")
        .as_str()
        .unwrap_or_default()
        .to_string();

    // Keep polling after the task settled: a read may not produce another artifact.
    for _ in 0..3 {
        let again = report_details(&router, &id).await;
        assert_eq!(
            at(&again.body, "/recommendationReportDetails/s3Keys"),
            at(&settled.body, "/recommendationReportDetails/s3Keys"),
            "polling must report the same key, got {:?}",
            again.body
        );
    }

    let (status, body) = s3(&router, "GET", &format!("/{REPORT_BUCKET}?list-type=2")).await;
    assert_eq!(
        status,
        200,
        "listing the report bucket must succeed, got {status} with {:?}",
        String::from_utf8_lossy(&body)
    );
    let listing = String::from_utf8_lossy(&body);
    assert_eq!(
        listing.matches("<Key>").count(),
        1,
        "the task wrote exactly one report file into {REPORT_BUCKET}, got {listing}"
    );
    assert!(
        listing.contains(&key),
        "the one object in the bucket is the key the task reports ({key}), got {listing}"
    );
}

/// One report file covers a bounded portfolio: a scope past that bound produces no file, so
/// the task names no location and says why — rather than rendering and uploading a document
/// whose size the store alone decides.
#[tokio::test]
async fn a_scope_past_what_one_report_file_covers_produces_none() {
    let (router, engine) = emulator();
    configure_report_bucket(
        "a scope past the bound",
        &router,
        Configured::ByAssessment,
        REPORT_BUCKET,
    )
    .await;
    {
        let state = engine
            .state::<ComAmazonawsMigrationhubstrategyAwsmigrationhubstrategyrecommendationState>();
        let mut store = state.lock();
        let portfolio = store.region_entry(TEST_REGION);
        // One row past the bound, counting the components the harness already seeded: the
        // ids are `ResourceId`s (`^[0-9a-b]+`) like the ones an import mints.
        let seeded = portfolio.servers.len() + portfolio.application_components.len();
        for index in seeded..=MAX_REPORT_ROWS {
            let id = format!("a{index:011}");
            portfolio.servers.insert(
                id.clone(),
                ServerRecord {
                    id,
                    ..Default::default()
                },
            );
        }
    }

    let id = start_report(&router, json!({"outputFormat": OUTPUT_FORMAT_JSON}))
        .await
        .string("/id");
    let settled = settled_details(&router, &id).await;
    for member in ["/s3Bucket", "/s3Keys"] {
        let pointer = format!("/recommendationReportDetails{member}");
        assert_eq!(
            at(&settled.body, &pointer),
            Value::Null,
            "a scope past what one report file covers writes none, so {member} must be absent, \
             got {:?}",
            at(&settled.body, &pointer)
        );
    }
    let message = settled.string("/recommendationReportDetails/statusMessage");
    assert!(
        message.len() <= STATUS_MESSAGE_MAX && message.contains("larger than"),
        "the message must say the portfolio in scope is larger than one report file covers, got \
         {message:?}"
    );

    // And nothing was uploaded: the bound is checked before the file is rendered.
    let (status, body) = s3(&router, "GET", &format!("/{REPORT_BUCKET}?list-type=2")).await;
    assert_eq!(
        status,
        200,
        "listing the report bucket must succeed, got {status} with {:?}",
        String::from_utf8_lossy(&body)
    );
    let listing = String::from_utf8_lossy(&body);
    assert_eq!(
        listing.matches("<Key>").count(),
        0,
        "no report file may be written for a scope past the bound, got {listing}"
    );
}
